def main():
    data = json.loads((CONTENT / 'legacy_pl.json').read_text(encoding='utf-8'))
    roles = {
        'Team Leader': 'Ръководител на екип',
        'Ambasador': 'Посланик',
        'Manager ds. importu aut z USA oraz Korei': 'Мениджър внос на автомобили от САЩ и Корея',
    }
    for manager in data['managers']:
        manager['role'] = roles[manager['role']]
    assert len(data['reviews']) == len(REVIEWS)
    for review, text in zip(data['reviews'], REVIEWS):
        review['text'] = text
    assert len(data['faqs']) == len(FAQ)
    for item, translated in zip(data['faqs'], FAQ):
        item.update(translated)
    (CONTENT / 'seed.json').write_text(json.dumps(data, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')


if __name__ == '__main__':
    main()
